DROP TRIGGER IF EXISTS trg_validate_liability_party_row ON public.liability_parties;
CREATE TRIGGER trg_validate_liability_party_row
  BEFORE INSERT OR UPDATE ON public.liability_parties
  FOR EACH ROW
